create table collection_saved_items (collection_id bigint not null, saved_item_id bigint not null, constraint uk_collection_saved_item primary key (collection_id, saved_item_id));
create table collections (created_at timestamp(6) not null, id bigint generated by default as identity, user_id bigint not null, name varchar(100) not null, description varchar(1000), primary key (id), constraint uk_collections_user_name unique (user_id, name));
create table reminders (completed boolean not null, created_at timestamp(6) not null, id bigint generated by default as identity, remind_at timestamp(6) not null, saved_item_id bigint not null, message varchar(500), primary key (id));
create table saved_item_shares (id bigint generated by default as identity, recipient_user_id bigint not null, saved_item_id bigint not null, shared_at timestamp(6) not null, primary key (id), constraint uk_saved_item_share_recipient unique (saved_item_id, recipient_user_id));
create table saved_item_tags (saved_item_id bigint not null, tag_id bigint not null, constraint uk_tag_saved_item primary key (tag_id, saved_item_id));
create table saved_items (is_favorite boolean not null, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), user_id bigint, content_type varchar(255) check (content_type in ('WEBPAGE','IMGAGE','TEXT','PDF')), description varchar(255), extracted_text TEXT, file_path varchar(255), language varchar(255), processing_status varchar(255) check (processing_status in ('PENDING','PROCESSING','COMPLETED','FAILED')), source_url varchar(255), title varchar(255), primary key (id));
create table subscriptions (expires_at timestamp(6), id bigint generated by default as identity, started_at timestamp(6) not null, user_id bigint not null unique, plan varchar(20) not null check (plan in ('FREE','PREMIUM')), primary key (id));
create table tags (created_at timestamp(6) not null, id bigint generated by default as identity, user_id bigint not null, name varchar(50) not null, primary key (id), constraint uk_tags_user_name unique (user_id, name));
create table users (created_at timestamp(6) not null, id bigint generated by default as identity, role varchar(20) not null check (role in ('USER','ADMIN')), username varchar(100) not null unique, email varchar(254) not null unique, password varchar(255) not null, primary key (id));
